"""Static code metrics — LOC and cyclomatic complexity."""

from __future__ import annotations

import ast
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterable


@dataclass
class FunctionMetrics:
    name: str
    path: str
    lineno: int
    loc: int
    sloc: int
    cyclomatic_complexity: int

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "path": self.path,
            "lineno": self.lineno,
            "loc": self.loc,
            "sloc": self.sloc,
            "cyclomatic_complexity": self.cyclomatic_complexity,
        }


@dataclass
class FileMetrics:
    path: str
    loc_physical: int
    loc_logical: int
    sloc: int
    comment_lines: int
    blank_lines: int
    cyclomatic_total: int
    cyclomatic_max: int
    functions: list[FunctionMetrics] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "path": self.path,
            "loc_physical": self.loc_physical,
            "loc_logical": self.loc_logical,
            "sloc": self.sloc,
            "comment_lines": self.comment_lines,
            "blank_lines": self.blank_lines,
            "cyclomatic_total": self.cyclomatic_total,
            "cyclomatic_max": self.cyclomatic_max,
            "function_count": len(self.functions),
            "functions": [fn.to_dict() for fn in self.functions],
        }


@dataclass
class PackageMetrics:
    label: str
    root: str
    files: list[FileMetrics] = field(default_factory=list)

    def totals(self) -> dict[str, Any]:
        function_count = sum(len(file.functions) for file in self.files)
        cyclomatic_total = sum(file.cyclomatic_total for file in self.files)
        cyclomatic_max = max((file.cyclomatic_max for file in self.files), default=0)
        return {
            "files": len(self.files),
            "loc_physical": sum(file.loc_physical for file in self.files),
            "loc_logical": sum(file.loc_logical for file in self.files),
            "sloc": sum(file.sloc for file in self.files),
            "comment_lines": sum(file.comment_lines for file in self.files),
            "blank_lines": sum(file.blank_lines for file in self.files),
            "cyclomatic_total": cyclomatic_total,
            "cyclomatic_max": cyclomatic_max,
            "cyclomatic_mean": round(cyclomatic_total / function_count, 2) if function_count else 0.0,
            "function_count": function_count,
        }

    def to_dict(self) -> dict[str, Any]:
        return {
            "label": self.label,
            "root": self.root,
            "totals": self.totals(),
            "files": [file.to_dict() for file in self.files],
        }


def _is_comment_or_blank(line: str) -> tuple[bool, bool]:
    stripped = line.strip()
    if not stripped:
        return False, True
    if stripped.startswith("#"):
        return True, False
    return False, False


def _logical_line_counts(lines: list[str]) -> tuple[int, int, int]:
    physical = len(lines)
    logical = 0
    comments = 0
    blanks = 0
    for line in lines:
        is_comment, is_blank = _is_comment_or_blank(line)
        if is_blank:
            blanks += 1
        elif is_comment:
            comments += 1
        else:
            logical += 1
    return physical, logical, comments, blanks


def _cyclomatic_complexity(node: ast.AST) -> int:
    complexity = 1
    for child in ast.walk(node):
        if isinstance(
            child,
            (
                ast.If,
                ast.For,
                ast.AsyncFor,
                ast.While,
                ast.With,
                ast.AsyncWith,
                ast.ExceptHandler,
            ),
        ):
            complexity += 1
        elif isinstance(child, ast.BoolOp):
            complexity += max(1, len(child.values) - 1)
        elif isinstance(child, ast.IfExp):
            complexity += 1
        elif isinstance(child, ast.Match):
            complexity += max(1, len(child.cases) - 1)
        elif isinstance(child, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)):
            complexity += 1
    return complexity


def _function_nodes(tree: ast.AST) -> Iterable[tuple[ast.AST, str, int]]:
    for node in tree.body if isinstance(tree, ast.Module) else []:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            yield node, node.name, node.lineno
        elif isinstance(node, ast.ClassDef):
            for child in node.body:
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    yield child, f"{node.name}.{child.name}", child.lineno


def analyze_file(path: Path, root: Path) -> FileMetrics:
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    loc_physical, loc_logical, comment_lines, blank_lines = _logical_line_counts(lines)

    try:
        tree = ast.parse(text, filename=str(path))
    except SyntaxError:
        return FileMetrics(
            path=str(path.relative_to(root)),
            loc_physical=loc_physical,
            loc_logical=loc_logical,
            sloc=0,
            comment_lines=comment_lines,
            blank_lines=blank_lines,
            cyclomatic_total=0,
            cyclomatic_max=0,
            functions=[],
        )

    functions: list[FunctionMetrics] = []
    sloc = 0
    for node, name, lineno in _function_nodes(tree):
        end_lineno = getattr(node, "end_lineno", lineno) or lineno
        fn_loc = max(1, end_lineno - lineno + 1)
        cc = _cyclomatic_complexity(node)
        sloc += fn_loc
        functions.append(
            FunctionMetrics(
                name=name,
                path=str(path.relative_to(root)),
                lineno=lineno,
                loc=fn_loc,
                sloc=fn_loc,
                cyclomatic_complexity=cc,
            )
        )

    if not functions:
        sloc = loc_logical

    cyclomatic_total = sum(fn.cyclomatic_complexity for fn in functions)
    cyclomatic_max = max((fn.cyclomatic_complexity for fn in functions), default=0)

    return FileMetrics(
        path=str(path.relative_to(root)),
        loc_physical=loc_physical,
        loc_logical=loc_logical,
        sloc=sloc,
        comment_lines=comment_lines,
        blank_lines=blank_lines,
        cyclomatic_total=cyclomatic_total,
        cyclomatic_max=cyclomatic_max,
        functions=functions,
    )


def analyze_package(root: Path, label: str) -> PackageMetrics:
    root = root.resolve()
    files: list[FileMetrics] = []
    for path in sorted(root.rglob("*.py")):
        if "__pycache__" in path.parts:
            continue
        if any(part in {".eval-venv", ".venv", "venv"} for part in path.parts):
            continue
        files.append(analyze_file(path, root))
    return PackageMetrics(label=label, root=str(root), files=files)


def compare_packages(left: PackageMetrics, right: PackageMetrics) -> dict[str, Any]:
    left_totals = left.totals()
    right_totals = right.totals()
    rows: list[dict[str, Any]] = []
    for key in (
        "files",
        "loc_physical",
        "loc_logical",
        "sloc",
        "cyclomatic_total",
        "cyclomatic_max",
        "cyclomatic_mean",
        "function_count",
    ):
        left_value = left_totals[key]
        right_value = right_totals[key]
        delta = right_value - left_value if isinstance(left_value, (int, float)) else None
        rows.append(
            {
                "metric": key,
                "left": left_value,
                "right": right_value,
                "delta": delta,
            }
        )
    return {
        "left_label": left.label,
        "right_label": right.label,
        "rows": rows,
    }


def format_code_metrics_table(package: PackageMetrics) -> str:
    headers = ["path", "sloc", "loc", "cc_total", "cc_max", "functions"]
    rows: list[list[str]] = []
    for file in package.files:
        rows.append(
            [
                file.path,
                str(file.sloc),
                str(file.loc_logical),
                str(file.cyclomatic_total),
                str(file.cyclomatic_max),
                str(len(file.functions)),
            ]
        )
    totals = package.totals()
    rows.append(
        [
            "TOTAL",
            str(totals["sloc"]),
            str(totals["loc_logical"]),
            str(totals["cyclomatic_total"]),
            str(totals["cyclomatic_max"]),
            str(totals["function_count"]),
        ]
    )
    widths = [len(h) for h in headers]
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))

    def fmt_row(cells: list[str]) -> str:
        return "| " + " | ".join(cell.ljust(widths[i]) for i, cell in enumerate(cells)) + " |"

    sep = "| " + " | ".join("-" * w for w in widths) + " |"
    lines = [fmt_row(headers), sep]
    for row in rows:
        lines.append(fmt_row(row))
    return "\n".join(lines)


def format_code_comparison_table(comparison: dict[str, Any]) -> str:
    headers = ["metric", comparison["left_label"], comparison["right_label"], "delta"]
    rows: list[list[str]] = []
    for row in comparison["rows"]:
        rows.append(
            [
                row["metric"],
                str(row["left"]),
                str(row["right"]),
                str(row["delta"]),
            ]
        )
    widths = [len(h) for h in headers]
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))

    def fmt_row(cells: list[str]) -> str:
        return "| " + " | ".join(cell.ljust(widths[i]) for i, cell in enumerate(cells)) + " |"

    sep = "| " + " | ".join("-" * w for w in widths) + " |"
    lines = [fmt_row(headers), sep]
    for row in rows:
        lines.append(fmt_row(row))
    return "\n".join(lines)

"""NEV log — in-game narrative/event log."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class EventKind(str, Enum):
    ACTION_APPLIED = "action_applied"
    STATE_TRANSITION = "state_transition"
    RULE_VIOLATION = "rule_violation"
    ACHIEVEMENT = "achievement"
    RESOURCE_DELTA = "resource_delta"
    ENTITY_SPAWN = "entity_spawn"
    ENTITY_DESPAWN = "entity_despawn"
    TERMINAL = "terminal"
    DEBUG = "debug"


class EventSeverity(str, Enum):
    INFO = "info"
    WARN = "warn"
    ERROR = "error"


@dataclass
class EventRecord:
    step_index: int
    sim_tick: int
    episode_id: str
    kind: EventKind
    severity: EventSeverity
    message: str
    action: dict[str, Any] | None = None
    transition: dict[str, Any] | None = None
    payload: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "step_index": self.step_index,
            "sim_tick": self.sim_tick,
            "episode_id": self.episode_id,
            "kind": self.kind.value,
            "severity": self.severity.value,
            "message": self.message,
            "action": self.action,
            "transition": self.transition,
            "payload": self.payload,
        }


@dataclass
class NevLog:
    """Append-only in-sim event log."""

    events: list[EventRecord] = field(default_factory=list)

    def cursor(self) -> int:
        return len(self.events)

    def append(self, record: EventRecord) -> None:
        self.events.append(record)

    def tail(self, count: int) -> list[EventRecord]:
        if count <= 0:
            return []
        return self.events[-count:]

    def export(self) -> list[dict[str, Any]]:
        return [event.to_dict() for event in self.events]

    def legacy_strings(self) -> list[str]:
        return [event.message for event in self.events]

    def diff_messages(self, other_messages: list[str]) -> str:
        left = self.legacy_strings()
        lines: list[str] = []
        max_len = max(len(left), len(other_messages))
        for index in range(max_len):
            expected = other_messages[index] if index < len(other_messages) else None
            actual = left[index] if index < len(left) else None
            if expected != actual:
                lines.append(f"  [{index}] expected={expected!r} actual={actual!r}")
        if not lines:
            return "NEV logs match"
        return "NEV diff:\n" + "\n".join(lines)

"""Monty policy loader — task-bundled Python opponent policies."""

from __future__ import annotations

import importlib.util
import sys
from pathlib import Path
from typing import Any, Callable

PolicyFn = Callable[[dict[str, Any], int, int], dict[str, Any]]

POLICIES_DIR = Path(__file__).resolve().parent.parent / "policies"


def _ensure_policies_path() -> None:
    policies_path = str(POLICIES_DIR)
    if policies_path not in sys.path:
        sys.path.insert(0, policies_path)


def _registry_choose_action(policy_id: str, state: dict[str, Any], seed: int, ply: int) -> dict[str, Any]:
    _ensure_policies_path()
    from registry import choose_action as registry_fn

    return registry_fn(policy_id, state, seed=seed, ply=ply)


def _load_module_policy(module_name: str, entry: str = "choose_action") -> PolicyFn:
    module_path = POLICIES_DIR / f"{module_name}.py"
    if not module_path.is_file():
        raise ValueError(f"policy module not found: {module_path}")
    _ensure_policies_path()
    spec = importlib.util.spec_from_file_location(f"tictactoe_policy_{module_name}", module_path)
    if spec is None or spec.loader is None:
        raise ValueError(f"cannot load policy module: {module_name}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    fn = getattr(module, entry, None)
    if fn is None:
        raise ValueError(f"policy module {module_name} missing entry {entry}")
    return fn


def resolve_policy(spec: dict[str, Any]) -> PolicyFn:
    kind = spec.get("kind", "registry")
    if kind == "registry":
        policy_id = str(spec["policy_id"])

        def registry_wrapper(public: dict[str, Any], seed: int, ply: int) -> dict[str, Any]:
            state = {
                "board": list(public["board"]),
                "turn": public["turn"],
                "winner": public.get("winner"),
            }
            return _registry_choose_action(policy_id, state, seed=seed, ply=ply)

        return registry_wrapper
    if kind == "monty_python":
        return _load_module_policy(str(spec["module"]), str(spec.get("entry", "choose_action")))
    raise ValueError(f"unknown policy kind: {kind}")


def public_dict_from_engine(public: Any) -> dict[str, Any]:
    return {
        "board": list(public.board),
        "turn": public.turn,
        "winner": public.winner,
    }

"""Observation callables — agent-facing projections."""

from __future__ import annotations

from typing import Any

from gold.render import build_render_state
from gold.state import PrivateState, PublicState


def project_observation(
    public: PublicState,
    private: PrivateState,
    profile: str = "llm_text",
) -> dict[str, Any]:
    if profile == "llm_text":
        render = build_render_state(public)
        return {
            "profile": profile,
            "board_text": render.ascii_board,
            "turn": public.turn,
            "winner": public.winner,
            "terminated": private.terminated,
        }
    if profile == "structured_facts":
        return {
            "profile": profile,
            "board": list(public.board),
            "turn": public.turn,
            "winner": public.winner,
            "step_index": private.step_index,
            "ply": private.ply,
        }
    if profile == "checkpoint_summary":
        return {
            "profile": profile,
            "episode_id": private.episode_id,
            "scenario_id": private.scenario_id,
            "step_index": private.step_index,
            "total_reward": private.total_reward,
            "terminated": private.terminated,
            "winner": public.winner,
        }
    raise ValueError(f"unknown observation profile: {profile}")

"""RenderState — visual projection from public state."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from gold.state import PublicState


@dataclass
class RenderState:
    profile: str
    ascii_board: str
    cell_labels: list[str]

    def to_dict(self) -> dict[str, Any]:
        return {
            "profile": self.profile,
            "ascii_board": self.ascii_board,
            "cell_labels": list(self.cell_labels),
        }


def cell_label(cell: str) -> str:
    if not cell:
        return "."
    return cell


def build_render_state(public: PublicState, profile: str = "ascii_tui") -> RenderState:
    labels = [cell_label(cell) for cell in public.board]
    rows = [
        " ".join(labels[0:3]),
        " ".join(labels[3:6]),
        " ".join(labels[6:9]),
    ]
    ascii_board = "\n".join(rows)
    return RenderState(profile=profile, ascii_board=ascii_board, cell_labels=labels)

"""Scenario runner — policy-vs-policy rollouts from rich task definitions."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from gold.core.nev import EventKind
from gold.engine import episode_id_from_task, TicTacToeEngine
from gold.mp_board import AGENT_IDS, MARK_TO_AGENT
from gold.monty import public_dict_from_engine, resolve_policy


TASKS_DIR = Path(__file__).resolve().parent.parent / "tasks"
FIXTURES_DIR = Path(__file__).resolve().parent.parent / "fixtures"


def load_task(task_path: Path) -> dict[str, Any]:
    return json.loads(task_path.read_text())


def _policy_spec(task: dict[str, Any], agent_id: str) -> dict[str, Any]:
    if agent_id == "agent_0":
        if "agent_0_policy" in task:
            return task["agent_0_policy"]
        if "x_policy" in task:
            return task["x_policy"]
    if agent_id == "agent_1":
        if "agent_1_policy" in task:
            return task["agent_1_policy"]
        if "o_policy" in task:
            return task["o_policy"]
    raise KeyError(f"no policy spec for {agent_id}")


def scenario_from_legacy(entry: dict[str, Any]) -> dict[str, Any]:
    agent_0_id = entry.get("agent_0_policy_id", entry.get("x_policy_id"))
    agent_1_id = entry.get("agent_1_policy_id", entry.get("o_policy_id"))
    return {
        "schema_version": "gamebench.task.v1",
        "task_id": entry["scenario_id"],
        "scenario_id": entry["scenario_id"],
        "seed": entry["seed"],
        "max_plies": entry.get("max_plies", 9),
        "opening_moves": list(entry.get("opening_moves", [])),
        "agent_0_policy": {"kind": "registry", "policy_id": agent_0_id},
        "agent_1_policy": {"kind": "registry", "policy_id": agent_1_id},
    }


def run_scenario(task: dict[str, Any]) -> dict[str, Any]:
    scenario_id = str(task["scenario_id"])
    seed = int(task.get("seed", 0))
    max_plies = int(task.get("max_plies", 9))
    opening_moves = list(task.get("opening_moves", []))

    policies = {
        agent_id: resolve_policy(_policy_spec(task, agent_id)) for agent_id in AGENT_IDS
    }

    engine = TicTacToeEngine()
    engine.reset(
        scenario_id=scenario_id,
        seed=seed,
        episode_id=episode_id_from_task(task),
        task_id=str(task.get("task_id", scenario_id)),
    )

    for action in opening_moves:
        engine.step(dict(action))

    plies = 0
    while not engine.private.terminated and not engine.private.truncated and plies < max_plies:
        public = public_dict_from_engine(engine.public)
        agent_id = MARK_TO_AGENT[engine.public.turn]
        action = policies[agent_id](public, seed, plies)
        engine.step(action)
        plies += 1

    if not engine.private.terminated and not engine.private.truncated:
        engine._append_nev(
            kind=EventKind.DEBUG,
            message=f"RolloutStopped(max_plies={max_plies})",
            payload={"max_plies": max_plies},
        )

    return {
        "scenario_id": scenario_id,
        "events": engine.nev.legacy_strings(),
        "nev": engine.nev.export(),
        "state": {
            "public": engine.public.to_dict(),
            "private": engine.private.to_dict(),
        },
    }

"""FastAPI container surface for Tic-Tac-Toe gold reference."""

from __future__ import annotations

import base64
import os
import sys
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

_GAMEBENCH_ROOT = Path(
    os.environ.get("GAMEBENCH_ROOT", "").strip() or str(Path(__file__).resolve().parents[3])
).resolve()
if str(_GAMEBENCH_ROOT) not in sys.path:
    sys.path.insert(0, str(_GAMEBENCH_ROOT))

from runtime.session_pool import SessionPool, SessionPoolConfig, SessionPoolFullError

from gold.core.checkpoint import RestoreReport
from gold.engine import episode_id_from_task, TicTacToeEngine
from gold.observations import project_observation
from gold.render import build_render_state
from gold.scenarios import run_scenario


class StepRequest(BaseModel):
    action: dict[str, Any]
    observation_profile: str = "llm_text"


class ResetRequest(BaseModel):
    scenario_id: str = "manual"
    seed: int = 0
    task_id: str | None = None


class ScenarioRequest(BaseModel):
    task: dict[str, Any]


class CheckpointExport(BaseModel):
    checkpoint_id: str
    blob: str


@dataclass
class RolloutSession:
    rollout_id: str
    engine: TicTacToeEngine
    checkpoints: dict[str, bytes] = field(default_factory=dict)


def create_app(pool_config: SessionPoolConfig | None = None) -> FastAPI:
    app = FastAPI(title="GameBench Tic-Tac-Toe Gold", version="0.1.0")
    pool = SessionPool[RolloutSession](pool_config or SessionPoolConfig.from_env())

    @app.get("/health")
    def health() -> dict[str, Any]:
        return {
            "ok": True,
            "engine": "tictactoe-singleplayer-gold",
            "env_family": "tictactoe-singleplayer",
            "pool": pool.stats(),
        }

    @app.get("/info")
    def info() -> dict[str, Any]:
        return {
            "env_family": "tictactoe-singleplayer",
            "capabilities": ["rollout", "checkpoint", "nev_log", "render_state", "session_pool"],
            "pool": pool.stats(),
        }

    @app.get("/pool")
    def pool_stats() -> dict[str, Any]:
        return pool.stats()

    @app.post("/pool/evict_idle")
    def evict_idle() -> dict[str, Any]:
        evicted = pool.evict_idle()
        return {"evicted": evicted, "pool": pool.stats()}

    @app.post("/rollout")
    def rollout(body: ScenarioRequest) -> dict[str, Any]:
        result = run_scenario(body.task)
        episode_id = episode_id_from_task(body.task)
        engine = TicTacToeEngine()
        engine.reset(
            scenario_id=result["scenario_id"],
            seed=int(body.task.get("seed", 0)),
            episode_id=episode_id,
            task_id=str(body.task.get("task_id", result["scenario_id"])),
        )
        rollout_id = episode_id
        task_id = str(body.task.get("task_id", result["scenario_id"]))
        seed = int(body.task.get("seed", 0))
        try:
            _admit_session(
                pool,
                rollout_id=rollout_id,
                engine=engine,
                seed=seed,
                task_id=task_id,
                terminated=bool(result["state"]["private"]["terminated"]),
            )
        except SessionPoolFullError as exc:
            raise HTTPException(status_code=429, detail={"message": "env session pool full", "pool": exc.stats})
        return {
            "rollout_id": rollout_id,
            "scenario_id": result["scenario_id"],
            "events": result["events"],
            "nev": result["nev"],
            "reward": result["state"]["private"]["total_reward"],
            "terminated": result["state"]["private"]["terminated"],
        }

    @app.post("/reset")
    def reset(body: ResetRequest) -> dict[str, Any]:
        task_id = body.task_id or body.scenario_id
        episode_id = episode_id_from_task(
            {
                "scenario_id": body.scenario_id,
                "seed": body.seed,
                "task_id": task_id,
            }
        )
        rollout_id = episode_id
        engine = TicTacToeEngine()
        engine.reset(
            scenario_id=body.scenario_id,
            seed=body.seed,
            episode_id=episode_id,
            task_id=task_id,
        )
        try:
            session = _admit_session(
                pool,
                rollout_id=rollout_id,
                engine=engine,
                seed=body.seed,
                task_id=task_id,
            )
        except SessionPoolFullError as exc:
            raise HTTPException(status_code=429, detail={"message": "env session pool full", "pool": exc.stats})
        return _session_payload(session)

    @app.post("/rollouts/{rollout_id}/step")
    def step(rollout_id: str, body: StepRequest) -> dict[str, Any]:
        session = _require_session(pool, rollout_id)
        session.engine.step(body.action)
        _touch_session(pool, session)
        payload = _session_payload(session, observation_profile=body.observation_profile)
        return payload

    @app.get("/rollouts/{rollout_id}/state")
    def state(rollout_id: str, observation_profile: str = "structured_facts") -> dict[str, Any]:
        session = _require_session(pool, rollout_id)
        pool.touch(rollout_id)
        return _session_payload(session, observation_profile=observation_profile)

    @app.get("/rollouts/{rollout_id}/events")
    def events(rollout_id: str) -> dict[str, Any]:
        session = _require_session(pool, rollout_id)
        pool.touch(rollout_id)
        engine = session.engine
        return {
            "rollout_id": rollout_id,
            "nev_cursor": engine.nev.cursor(),
            "events": engine.nev.export(),
            "legacy": engine.nev.legacy_strings(),
        }

    @app.delete("/rollouts/{rollout_id}")
    def close_rollout(rollout_id: str) -> dict[str, Any]:
        released = pool.release(rollout_id)
        if not released:
            raise HTTPException(status_code=404, detail="rollout not found")
        return {"rollout_id": rollout_id, "released": True, "pool": pool.stats()}

    @app.post("/rollouts/{rollout_id}/checkpoints")
    def save_checkpoint(rollout_id: str) -> dict[str, Any]:
        session = _require_session(pool, rollout_id)
        checkpoint_id = str(uuid.uuid4())
        blob = session.engine.checkpoint_bytes()
        session.checkpoints[checkpoint_id] = blob
        pool.touch(rollout_id)
        return {
            "checkpoint_id": checkpoint_id,
            "bytes": len(blob),
            "nev_cursor": session.engine.nev.cursor(),
        }

    @app.get("/checkpoints/{checkpoint_id}/export")
    def export_checkpoint(checkpoint_id: str) -> dict[str, Any]:
        for pooled in pool.values():
            session = pooled.value
            if checkpoint_id in session.checkpoints:
                blob = session.checkpoints[checkpoint_id]
                return {
                    "checkpoint_id": checkpoint_id,
                    "blob": base64.b64encode(blob).decode("ascii"),
                }
        raise HTTPException(status_code=404, detail="checkpoint not found")

    @app.post("/checkpoints/import")
    def import_checkpoint(body: CheckpointExport) -> dict[str, Any]:
        rollout_id = str(uuid.uuid4())
        engine = TicTacToeEngine()
        blob = base64.b64decode(body.blob.encode("ascii"))
        nev_count = engine.restore_checkpoint(blob)
        report = RestoreReport(bytes=len(blob), wall_ms=0.0, nev_events_restored=nev_count)
        try:
            session = _admit_session(pool, rollout_id=rollout_id, engine=engine)
        except SessionPoolFullError as exc:
            raise HTTPException(status_code=429, detail={"message": "env session pool full", "pool": exc.stats})
        return {
            "rollout_id": rollout_id,
            "restore_report": report.to_dict(),
            "state": _session_payload(session),
        }

    @app.post("/run_scenario")
    def run_scenario_route(body: ScenarioRequest) -> dict[str, Any]:
        return run_scenario(body.task)

    return app


def _admit_session(
    pool: SessionPool[RolloutSession],
    *,
    rollout_id: str,
    engine: TicTacToeEngine,
    seed: int | None = None,
    task_id: str | None = None,
    terminated: bool = False,
) -> RolloutSession:
    session = RolloutSession(rollout_id=rollout_id, engine=engine)
    pooled = pool.upsert(
        rollout_id,
        session,
        seed=seed,
        task_id=task_id,
    )
    if terminated:
        pool.touch(rollout_id, terminated=True)
        pool.release_if_terminal(rollout_id)
    return pooled.value


def _require_session(pool: SessionPool[RolloutSession], rollout_id: str) -> RolloutSession:
    pooled = pool.get(rollout_id)
    if pooled is None:
        raise HTTPException(status_code=404, detail="rollout not found")
    return pooled.value


def _touch_session(pool: SessionPool[RolloutSession], session: RolloutSession) -> None:
    engine = session.engine
    terminated = engine.private.terminated or engine.private.truncated
    pool.touch(session.rollout_id, terminated=terminated)


def _session_payload(session: RolloutSession, observation_profile: str = "llm_text") -> dict[str, Any]:
    engine = session.engine
    render = build_render_state(engine.public)
    observation = project_observation(engine.public, engine.private, profile=observation_profile)
    return {
        "rollout_id": session.rollout_id,
        "public": engine.public.to_dict(),
        "private": engine.private.to_dict(),
        "observation": observation,
        "render_state": render.to_dict(),
        "nev_tail": engine.nev.export()[-5:],
        "nev_cursor": engine.nev.cursor(),
    }

"""Public/private state split for Tic-Tac-Toe."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass
class PublicState:
    board: list[str]
    turn: str
    winner: str | None

    def to_dict(self) -> dict[str, Any]:
        return {"board": list(self.board), "turn": self.turn, "winner": self.winner}

    def diff(self, other: PublicState) -> dict[str, Any]:
        changes: dict[str, Any] = {}
        if self.board != other.board:
            changes["board"] = {"from": other.board, "to": self.board}
        if self.turn != other.turn:
            changes["turn"] = {"from": other.turn, "to": self.turn}
        if self.winner != other.winner:
            changes["winner"] = {"from": other.winner, "to": self.winner}
        return changes


@dataclass
class PrivateState:
    episode_id: str
    scenario_id: str
    seed: int
    step_index: int
    ply: int
    reward_last: float = 0.0
    total_reward: float = 0.0
    terminated: bool = False
    truncated: bool = False

    def to_dict(self) -> dict[str, Any]:
        return {
            "episode_id": self.episode_id,
            "scenario_id": self.scenario_id,
            "seed": self.seed,
            "step_index": self.step_index,
            "ply": self.ply,
            "reward_last": self.reward_last,
            "total_reward": self.total_reward,
            "terminated": self.terminated,
            "truncated": self.truncated,
        }

    def diff(self, other: PrivateState) -> dict[str, Any]:
        changes: dict[str, Any] = {}
        for key in (
            "step_index",
            "ply",
            "reward_last",
            "total_reward",
            "terminated",
            "truncated",
        ):
            left = getattr(self, key)
            right = getattr(other, key)
            if left != right:
                changes[key] = {"from": right, "to": left}
        return changes


@dataclass
class SimSnapshot:
    public: PublicState
    private: PrivateState
    nev_events: list[dict[str, Any]] = field(default_factory=list)

