#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EventKind {
    ActionApplied,
    StateTransition,
    RuleViolation,
    Achievement,
    ResourceDelta,
    EntitySpawn,
    EntityDespawn,
    Terminal,
    Debug,
}

impl EventKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventKind::ActionApplied => "action_applied",
            EventKind::StateTransition => "state_transition",
            EventKind::RuleViolation => "rule_violation",
            EventKind::Achievement => "achievement",
            EventKind::ResourceDelta => "resource_delta",
            EventKind::EntitySpawn => "entity_spawn",
            EventKind::EntityDespawn => "entity_despawn",
            EventKind::Terminal => "terminal",
            EventKind::Debug => "debug",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EventSeverity {
    Info,
    Warn,
    Error,
}

impl EventSeverity {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventSeverity::Info => "info",
            EventSeverity::Warn => "warn",
            EventSeverity::Error => "error",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EventRecord {
    pub step_index: i64,
    pub sim_tick: i64,
    pub episode_id: String,
    pub kind: EventKind,
    pub severity: EventSeverity,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub action: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transition: Option<Value>,
    #[serde(default)]
    pub payload: Value,
}

impl EventRecord {
    pub fn to_dict(&self) -> Value {
        serde_json::json!({
            "step_index": self.step_index,
            "sim_tick": self.sim_tick,
            "episode_id": self.episode_id,
            "kind": self.kind.as_str(),
            "severity": self.severity.as_str(),
            "message": self.message,
            "action": self.action,
            "transition": self.transition,
            "payload": self.payload,
        })
    }
}

#[derive(Debug, Clone)]
pub struct NevLog {
    pub events: Vec<EventRecord>,
}

impl NevLog {
    pub fn new() -> Self {
        NevLog { events: Vec::new() }
    }

    pub fn cursor(&self) -> usize {
        self.events.len()
    }

    pub fn append(&mut self, record: EventRecord) {
        self.events.push(record);
    }

    pub fn export(&self) -> Vec<Value> {
        self.events.iter().map(|e| e.to_dict()).collect()
    }

    pub fn legacy_strings(&self) -> Vec<String> {
        self.events.iter().map(|e| e.message.clone()).collect()
    }
}

/// Deterministic Tic-Tac-Toe rollout policies (registry port).

use sha2::{Digest, Sha256};

use crate::board::{legal_positions, winner_for};

const CORNERS: [usize; 4] = [0, 2, 6, 8];
const EDGES: [usize; 4] = [1, 3, 5, 7];

fn opponent(player: &str) -> &'static str {
    if player == "X" { "O" } else { "X" }
}

fn winning_position(board: &[String; 9], player: &str) -> Option<usize> {
    for &line in &crate::board::WIN_LINES {
        let a = &board[line[0]];
        let b = &board[line[1]];
        let c = &board[line[2]];
        let count_player = [a.as_str(), b.as_str(), c.as_str()]
            .iter()
            .filter(|&&m| m == player)
            .count();
        let count_empty = [a.as_str(), b.as_str(), c.as_str()]
            .iter()
            .filter(|&&m| m.is_empty())
            .count();
        if count_player == 2 && count_empty == 1 {
            if a.is_empty() {
                return Some(line[0]);
            }
            if b.is_empty() {
                return Some(line[1]);
            }
            if c.is_empty() {
                return Some(line[2]);
            }
        }
    }
    None
}

fn seeded_order(values: &[usize], seed: i64, ply: i64, namespace: &str) -> Vec<usize> {
    let mut pairs: Vec<(String, usize)> = values
        .iter()
        .map(|&v| {
            let input = format!("{}:{}:{}:{}", namespace, seed, ply, v);
            let hash = hex::encode(Sha256::digest(input.as_bytes()));
            (hash, v)
        })
        .collect();
    pairs.sort_by(|a, b| a.0.cmp(&b.0));
    pairs.into_iter().map(|(_, v)| v).collect()
}

pub fn choose_position(policy_id: &str, board: &[String; 9], turn: &str, seed: i64, ply: i64) -> usize {
    let legal = legal_positions(board);

    match policy_id {
        "first_legal_v1" => legal[0],
        "last_legal_v1" => legal[legal.len() - 1],
        "center_first_v1" => {
            if legal.contains(&4) {
                4
            } else {
                legal[0]
            }
        }
        "corner_first_v1" => {
            let mut found = None;
            for &p in &CORNERS {
                if legal.contains(&p) {
                    found = Some(p);
                    break;
                }
            }
            found.unwrap_or(legal[0])
        }
        "edge_first_v1" => {
            let mut found = None;
            for &p in &EDGES {
                if legal.contains(&p) {
                    found = Some(p);
                    break;
                }
            }
            found.unwrap_or(legal[0])
        }
        "win_block_center_v1" => {
            winning_position(board, turn)
                .or_else(|| winning_position(board, opponent(turn)))
                .or_else(|| if legal.contains(&4) { Some(4) } else { None })
                .or_else(|| {
                    for &p in &CORNERS {
                        if legal.contains(&p) {
                            return Some(p);
                        }
                    }
                    None
                })
                .unwrap_or(legal[0])
        }
        "block_win_center_v1" => {
            winning_position(board, opponent(turn))
                .or_else(|| winning_position(board, turn))
                .or_else(|| if legal.contains(&4) { Some(4) } else { None })
                .or_else(|| {
                    for &p in &CORNERS {
                        if legal.contains(&p) {
                            return Some(p);
                        }
                    }
                    None
                })
                .unwrap_or(legal[0])
        }
        "mirror_preferred_v1" => {
            // order: 8,6,2,0,4,7,5,3,1
            let order = [8, 6, 2, 0, 4, 7, 5, 3, 1];
            for &p in &order {
                if legal.contains(&p) {
                    return p;
                }
            }
            legal[0]
        }
        "seeded_legal_v1" => {
            seeded_order(&legal, seed, ply, "tictactoe.seeded_legal_v1")[0]
        }
        "seeded_win_block_v1" => {
            winning_position(board, turn)
                .or_else(|| winning_position(board, opponent(turn)))
                .unwrap_or_else(|| seeded_order(&legal, seed, ply, "tictactoe.seeded_win_block_v1")[0])
        }
        _ => {
            // Fallback for minimax - we inline a simple version
            if policy_id == "minimax_v1" {
                minimax_choose_position(board, turn)
            } else {
                legal[0]
            }
        }
    }
}

fn minimax_score(board: &[String; 9], to_move: &str, maximizing_mark: &str) -> i32 {
    // Check terminal
    if let Some(w) = winner_for(board) {
        return if w == maximizing_mark { 1 } else { -1 };
    }
    let legal: Vec<usize> = (0..9).filter(|&i| board[i].is_empty()).collect();
    if legal.is_empty() {
        return 0; // draw
    }

    if to_move == maximizing_mark {
        let mut best = -2;
        for &idx in &legal {
            let mut next = board.clone();
            next[idx] = to_move.to_string();
            let s = minimax_score(&next, opponent(to_move), maximizing_mark);
            if s > best {
                best = s;
            }
        }
        best
    } else {
        let mut best = 2;
        for &idx in &legal {
            let mut next = board.clone();
            next[idx] = to_move.to_string();
            let s = minimax_score(&next, opponent(to_move), maximizing_mark);
            if s < best {
                best = s;
            }
        }
        best
    }
}

fn minimax_choose_position(board: &[String; 9], mark: &str) -> usize {
    let legal: Vec<usize> = (0..9).filter(|&i| board[i].is_empty()).collect();
    if legal.is_empty() {
        panic!("no legal positions");
    }

    // Check immediate win
    if let Some(pos) = winning_position(board, mark) {
        return pos;
    }
    // Check immediate block
    if let Some(pos) = winning_position(board, opponent(mark)) {
        return pos;
    }

    let mut best_score = -2;
    let mut best_moves: Vec<usize> = Vec::new();
    for &idx in &legal {
        let mut next = board.clone();
        next[idx] = mark.to_string();
        let score = minimax_score(&next, opponent(mark), mark);
        if score > best_score {
            best_score = score;
            best_moves = vec![idx];
        } else if score == best_score {
            best_moves.push(idx);
        }
    }
    best_moves[0]
}

pub fn choose_action(
    policy_id: &str,
    board: &[String; 9],
    turn: &str,
    seed: i64,
    ply: i64,
) -> serde_json::Value {
    let pos = choose_position(policy_id, board, turn, seed, ply);
    serde_json::json!({"player": turn, "position": pos})
}

/// Public/private state split for Tic-Tac-Toe.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PublicState {
    pub board: [String; 9],
    pub turn: String,
    pub winner: Option<String>,
}

impl PublicState {
    pub fn diff(&self, other: &PublicState) -> serde_json::Value {
        use serde_json::json;
        let mut changes = serde_json::Map::new();
        if self.board != other.board {
            changes.insert(
                "board".into(),
                json!({"from": other.board, "to": self.board}),
            );
        }
        if self.turn != other.turn {
            changes.insert(
                "turn".into(),
                json!({"from": other.turn, "to": self.turn}),
            );
        }
        if self.winner != other.winner {
            changes.insert(
                "winner".into(),
                json!({"from": other.winner, "to": self.winner}),
            );
        }
        serde_json::Value::Object(changes)
    }

    pub fn to_dict(&self) -> serde_json::Value {
        serde_json::json!({
            "board": self.board,
            "turn": self.turn,
            "winner": self.winner,
        })
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrivateState {
    pub episode_id: String,
    pub scenario_id: String,
    pub seed: i64,
    pub step_index: i64,
    pub ply: i64,
    pub reward_last: f64,
    pub total_reward: f64,
    pub terminated: bool,
    pub truncated: bool,
}

impl PrivateState {
    pub fn to_dict(&self) -> serde_json::Value {
        serde_json::json!({
            "episode_id": self.episode_id,
            "scenario_id": self.scenario_id,
            "seed": self.seed,
            "step_index": self.step_index,
            "ply": self.ply,
            "reward_last": self.reward_last,
            "total_reward": self.total_reward,
            "terminated": self.terminated,
            "truncated": self.truncated,
        })
    }
}

#[derive(Debug, Clone)]
pub struct SimSnapshot {
    pub public: PublicState,
    pub private: PrivateState,
    pub nev_events: Vec<serde_json::Value>,
}

/// CLI binary: read a scenario entry JSON on stdin, write {"events": [...]} on stdout.

use std::io::{self, Read};

use serde_json::Value;

use scenario::board;
use scenario::engine::TicTacToeEngine;
use scenario::policy;

fn scenario_from_legacy(entry: &Value) -> Value {
    let agent_0_id = entry
        .get("agent_0_policy_id")
        .or_else(|| entry.get("x_policy_id"))
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let agent_1_id = entry
        .get("agent_1_policy_id")
        .or_else(|| entry.get("o_policy_id"))
        .and_then(|v| v.as_str())
        .unwrap_or("");
    serde_json::json!({
        "schema_version": "gamebench.task.v1",
        "task_id": entry["scenario_id"],
        "scenario_id": entry["scenario_id"],
        "seed": entry.get("seed").and_then(|v| v.as_i64()).unwrap_or(0),
        "max_plies": entry.get("max_plies").and_then(|v| v.as_i64()).unwrap_or(9),
        "opening_moves": entry.get("opening_moves").and_then(|v| v.as_array()).cloned().unwrap_or_default(),
        "agent_0_policy": serde_json::json!({"kind": "registry", "policy_id": agent_0_id}),
        "agent_1_policy": serde_json::json!({"kind": "registry", "policy_id": agent_1_id}),
    })
}

fn policy_spec(task: &Value, agent_id: &str) -> String {
    if agent_id == "agent_0" {
        if let Some(p) = task.get("agent_0_policy").and_then(|v| v.get("policy_id")).and_then(|v| v.as_str()) {
            return p.to_string();
        }
        if let Some(p) = task.get("x_policy").and_then(|v| v.get("policy_id")).and_then(|v| v.as_str()) {
            return p.to_string();
        }
    }
    if agent_id == "agent_1" {
        if let Some(p) = task.get("agent_1_policy").and_then(|v| v.get("policy_id")).and_then(|v| v.as_str()) {
            return p.to_string();
        }
        if let Some(p) = task.get("o_policy").and_then(|v| v.get("policy_id")).and_then(|v| v.as_str()) {
            return p.to_string();
        }
    }
    panic!("no policy spec for {}", agent_id);
}

fn run_scenario(task: &Value) -> Value {
    let scenario_id = task["scenario_id"].as_str().unwrap_or("unknown");
    let seed = task.get("seed").and_then(|v| v.as_i64()).unwrap_or(0);
    let max_plies = task.get("max_plies").and_then(|v| v.as_i64()).unwrap_or(9);
    let opening_moves = task
        .get("opening_moves")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();

    // Resolve policies
    let policy_0 = policy_spec(task, "agent_0");
    let policy_1 = policy_spec(task, "agent_1");

    let mut engine = TicTacToeEngine::new();

    let episode_id = task
        .get("episode_id")
        .and_then(|v| v.as_str());
    let task_id = task
        .get("task_id")
        .and_then(|v| v.as_str());
    engine.reset(scenario_id, seed, episode_id, task_id);

    for action in &opening_moves {
        engine.step(action);
    }

    let mut plies = 0i64;
    while !engine.private.terminated && !engine.private.truncated && plies < max_plies {
        let turn = engine.public.turn.clone();
        let agent_id = board::mark_to_agent(&turn);
        let policy_id = if agent_id == "agent_0" {
            &policy_0
        } else {
            &policy_1
        };
        let action = policy::choose_action(policy_id, &engine.public.board, &turn, seed, plies);
        engine.step(&action);
        plies += 1;
    }

    if !engine.private.terminated && !engine.private.truncated {
        engine.append_nev(
            scenario::nev::EventKind::Debug,
            &format!("RolloutStopped(max_plies={})", max_plies),
            scenario::nev::EventSeverity::Info,
            None,
            None,
            Some(&serde_json::json!({"max_plies": max_plies})),
        );
    }

    serde_json::json!({
        "scenario_id": scenario_id,
        "events": engine.nev.legacy_strings(),
    })
}

fn main() {
    let mut input = String::new();
    io::stdin()
        .read_to_string(&mut input)
        .expect("failed to read stdin");
    let entry: Value = serde_json::from_str(&input).expect("invalid JSON on stdin");
    let task = scenario_from_legacy(&entry);
    let result = run_scenario(&task);
    let output = serde_json::json!({"events": result["events"]});
    println!("{}", serde_json::to_string(&output).unwrap());
}

/// Board primitives — canonical Tic-Tac-Toe win lines, mark-to-agent mapping.

pub const WIN_LINES: [[usize; 3]; 8] = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6],
];

pub const AGENT_IDS: [&str; 2] = ["agent_0", "agent_1"];
pub const MARKS: [&str; 2] = ["X", "O"];

pub fn mark_to_agent(mark: &str) -> &'static str {
    match mark {
        "X" => "agent_0",
        "O" => "agent_1",
        _ => panic!("unknown mark: {mark}"),
    }
}

pub fn winner_for(board: &[String; 9]) -> Option<String> {
    for &line in &WIN_LINES {
        let a = &board[line[0]];
        let b = &board[line[1]];
        let c = &board[line[2]];
        if !a.is_empty() && a == b && b == c {
            return Some(a.clone());
        }
    }
    None
}

pub fn legal_positions(board: &[String; 9]) -> Vec<usize> {
    let mut out = Vec::with_capacity(9);
    for (i, cell) in board.iter().enumerate() {
        if cell.is_empty() {
            out.push(i);
        }
    }
    out
}

/// Authoritative Tic-Tac-Toe simulation engine — port of gold_python/engine.py.

use sha2::{Digest, Sha256};

use crate::board::{mark_to_agent, winner_for, MARKS};
use crate::nev::{EventKind, EventRecord, EventSeverity, NevLog};
use crate::state::{PrivateState, PublicState, SimSnapshot};

pub fn config_hash(scenario_id: &str, seed: i64) -> String {
    let input = format!("tictactoe-singleplayer:{}:{}", scenario_id, seed);
    let digest = hex::encode(Sha256::digest(input.as_bytes()));
    format!("sha256:{}", digest)
}

fn episode_id_for_task(scenario_id: &str, seed: i64, task_id: Option<&str>) -> String {
    let key = task_id.unwrap_or(scenario_id);
    let input = format!("gamebench.tictactoe-singleplayer.episode:{}:{}", key, seed);
    let digest = hex::encode(Sha256::digest(input.as_bytes()));
    digest[..32].to_string()
}

fn episode_id_from_task(task: &serde_json::Value) -> String {
    if let Some(eid) = task.get("episode_id").and_then(|v| v.as_str()) {
        return eid.to_string();
    }
    let scenario_id = task["scenario_id"].as_str().unwrap_or("unknown");
    let seed = task.get("seed").and_then(|v| v.as_i64()).unwrap_or(0);
    let task_id = task
        .get("task_id")
        .and_then(|v| v.as_str())
        .unwrap_or(scenario_id);
    episode_id_for_task(scenario_id, seed, Some(task_id))
}

pub struct TicTacToeEngine {
    pub public: PublicState,
    pub private: PrivateState,
    pub nev: NevLog,
}

impl TicTacToeEngine {
    pub fn new() -> Self {
        TicTacToeEngine {
            public: PublicState {
                board: Default::default(),
                turn: "X".to_string(),
                winner: None,
            },
            private: PrivateState {
                episode_id: String::new(),
                scenario_id: String::new(),
                seed: 0,
                step_index: 0,
                ply: 0,
                reward_last: 0.0,
                total_reward: 0.0,
                terminated: false,
                truncated: false,
            },
            nev: NevLog::new(),
        }
    }

    pub fn reset(
        &mut self,
        scenario_id: &str,
        seed: i64,
        episode_id: Option<&str>,
        task_id: Option<&str>,
    ) -> SimSnapshot {
        let empty_board: [String; 9] = Default::default();
        self.public = PublicState {
            board: empty_board,
            turn: "X".to_string(),
            winner: None,
        };
        let resolved_episode_id = episode_id
            .map(|s| s.to_string())
            .unwrap_or_else(|| episode_id_for_task(scenario_id, seed, task_id));
        self.private = PrivateState {
            episode_id: resolved_episode_id,
            scenario_id: scenario_id.to_string(),
            seed,
            step_index: 0,
            ply: 0,
            reward_last: 0.0,
            total_reward: 0.0,
            terminated: false,
            truncated: false,
        };
        self.nev = NevLog::new();
        self.append_nev(
            EventKind::StateTransition,
            &format!("GameStarted({})", scenario_id),
            EventSeverity::Info,
            None,
            None,
            Some(&serde_json::json!({"scenario_id": scenario_id, "seed": seed})),
        );
        self.snapshot()
    }

    pub fn step(
        &mut self,
        action: &serde_json::Value,
    ) -> (SimSnapshot, Option<EventRecord>) {
        if self.private.terminated || self.private.truncated {
            let violation = self.append_nev(
                EventKind::RuleViolation,
                "game is already over",
                EventSeverity::Error,
                Some(action.clone()),
                None,
                Some(&serde_json::json!({"reason": "terminal"})),
            );
            return (self.snapshot(), Some(violation));
        }

        let player = action["player"].as_str().unwrap_or("").to_string();
        let position = action["position"].as_i64().unwrap_or(-1) as usize;

        if player != self.public.turn {
            let violation = self.append_nev(
                EventKind::RuleViolation,
                &format!("expected {} to move", self.public.turn),
                EventSeverity::Error,
                Some(action.clone()),
                None,
                Some(&serde_json::json!({"expected_turn": self.public.turn, "player": player})),
            );
            return (self.snapshot(), Some(violation));
        }

        if position >= 9 {
            let violation = self.append_nev(
                EventKind::RuleViolation,
                "position out of range",
                EventSeverity::Error,
                Some(action.clone()),
                None,
                Some(&serde_json::json!({"position": position})),
            );
            return (self.snapshot(), Some(violation));
        }

        if !self.public.board[position].is_empty() {
            let violation = self.append_nev(
                EventKind::RuleViolation,
                "position already occupied",
                EventSeverity::Error,
                Some(action.clone()),
                None,
                Some(&serde_json::json!({"position": position, "cell": self.public.board[position]})),
            );
            return (self.snapshot(), Some(violation));
        }

        let prev_public = PublicState {
            board: self.public.board.clone(),
            turn: self.public.turn.clone(),
            winner: self.public.winner.clone(),
        };

        self.public.board[position] = player.clone();
        self.private.ply += 1;
        self.private.step_index += 1;

        let transition = self.public.diff(&prev_public);
        let record = self.append_nev(
            EventKind::ActionApplied,
            &format!("MoveApplied({},{})", player, position),
            EventSeverity::Info,
            Some(action.clone()),
            Some(transition),
            Some(&serde_json::json!({"player": player, "position": position})),
        );

        let winner = winner_for(&self.public.board);
        if let Some(w) = winner {
            self.public.winner = Some(w.clone());
            self.private.terminated = true;
            self.private.reward_last = 1.0;
            self.private.total_reward += 1.0;
            self.append_nev(
                EventKind::Terminal,
                &format!("GameEnded({},win)", w),
                EventSeverity::Info,
                None,
                None,
                Some(&serde_json::json!({"winner": w, "reason": "win"})),
            );
        } else if self.public.board.iter().all(|c| !c.is_empty()) {
            self.public.winner = Some("draw".to_string());
            self.private.terminated = true;
            self.private.reward_last = 0.0;
            self.append_nev(
                EventKind::Terminal,
                "GameEnded(draw,draw)",
                EventSeverity::Info,
                None,
                None,
                Some(&serde_json::json!({"winner": "draw", "reason": "draw"})),
            );
        } else {
            let next_turn = if player == "X" { "O" } else { "X" };
            self.public.turn = next_turn.to_string();
            self.private.reward_last = 0.0;
            self.append_nev(
                EventKind::StateTransition,
                &format!("TurnStarted({})", next_turn),
                EventSeverity::Info,
                None,
                None,
                Some(&serde_json::json!({"turn": next_turn})),
            );
        }

        (self.snapshot(), Some(record))
    }

    pub fn snapshot(&self) -> SimSnapshot {
        SimSnapshot {
            public: PublicState {
                board: self.public.board.clone(),
                turn: self.public.turn.clone(),
                winner: self.public.winner.clone(),
            },
            private: PrivateState {
                episode_id: self.private.episode_id.clone(),
                scenario_id: self.private.scenario_id.clone(),
                seed: self.private.seed,
                step_index: self.private.step_index,
                ply: self.private.ply,
                reward_last: self.private.reward_last,
                total_reward: self.private.total_reward,
                terminated: self.private.terminated,
                truncated: self.private.truncated,
            },
            nev_events: self.nev.export(),
        }
    }

    /// Public helper that exactly mirrors the Python _append_nev.
    /// Matching the Python signature for use by the scenario runner.
    pub fn append_nev(
        &mut self,
        kind: EventKind,
        message: &str,
        severity: EventSeverity,
        action: Option<serde_json::Value>,
        transition: Option<serde_json::Value>,
        payload: Option<&serde_json::Value>,
    ) -> EventRecord {
        let record = EventRecord {
            step_index: self.private.step_index,
            sim_tick: self.private.step_index,
            episode_id: self.private.episode_id.clone(),
            kind,
            severity,
            message: message.to_string(),
            action,
            transition,
            payload: payload.cloned().unwrap_or(serde_json::Value::Object(Default::default())),
        };
        self.nev.append(record.clone());
        record
    }
}

