/// NEV log — in-game narrative/event log.

use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EventKind {
    ActionApplied,
    StateTransition,
    RuleViolation,
    Achievement,
    ResourceDelta,
    EntitySpawn,
    EntityDespawn,
    Terminal,
    Debug,
}

impl EventKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventKind::ActionApplied => "action_applied",
            EventKind::StateTransition => "state_transition",
            EventKind::RuleViolation => "rule_violation",
            EventKind::Achievement => "achievement",
            EventKind::ResourceDelta => "resource_delta",
            EventKind::EntitySpawn => "entity_spawn",
            EventKind::EntityDespawn => "entity_despawn",
            EventKind::Terminal => "terminal",
            EventKind::Debug => "debug",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EventSeverity {
    Info,
    Warn,
    Error,
}

impl EventSeverity {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventSeverity::Info => "info",
            EventSeverity::Warn => "warn",
            EventSeverity::Error => "error",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EventRecord {
    pub step_index: i64,
    pub sim_tick: i64,
    pub episode_id: String,
    pub kind: EventKind,
    pub severity: EventSeverity,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub action: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transition: Option<Value>,
    #[serde(default)]
    pub payload: Value,
}

impl EventRecord {
    pub fn to_dict(&self) -> Value {
        serde_json::json!({
            "step_index": self.step_index,
            "sim_tick": self.sim_tick,
            "episode_id": self.episode_id,
            "kind": self.kind.as_str(),
            "severity": self.severity.as_str(),
            "message": self.message,
            "action": self.action,
            "transition": self.transition,
            "payload": self.payload,
        })
    }
}

#[derive(Debug, Clone)]
pub struct NevLog {
    pub events: Vec<EventRecord>,
}

impl NevLog {
    pub fn new() -> Self {
        NevLog { events: Vec::new() }
    }

    pub fn cursor(&self) -> usize {
        self.events.len()
    }

    pub fn append(&mut self, record: EventRecord) {
        self.events.push(record);
    }

    pub fn export(&self) -> Vec<Value> {
        self.events.iter().map(|e| e.to_dict()).collect()
    }

    pub fn legacy_strings(&self) -> Vec<String> {
        self.events.iter().map(|e| e.message.clone()).collect()
    }
}

/// Deterministic Tic-Tac-Toe rollout policies (registry port).

use sha2::{Digest, Sha256};

use crate::board::{legal_positions, winner_for};

const CORNERS: [usize; 4] = [0, 2, 6, 8];
const EDGES: [usize; 4] = [1, 3, 5, 7];

fn opponent(player: &str) -> &'static str {
    if player == "X" { "O" } else { "X" }
}

fn winning_position(board: &[String; 9], player: &str) -> Option<usize> {
    for &line in &crate::board::WIN_LINES {
        let a = &board[line[0]];
        let b = &board[line[1]];
        let c = &board[line[2]];
        let count_player = [a.as_str(), b.as_str(), c.as_str()]
            .iter()
            .filter(|&&m| m == player)
            .count();
        let count_empty = [a.as_str(), b.as_str(), c.as_str()]
            .iter()
            .filter(|&&m| m.is_empty())
            .count();
        if count_player == 2 && count_empty == 1 {
            if a.is_empty() {
                return Some(line[0]);
            }
            if b.is_empty() {
                return Some(line[1]);
            }
            if c.is_empty() {
                return Some(line[2]);
            }
        }
    }
    None
}

fn seeded_order(values: &[usize], seed: i64, ply: i64, namespace: &str) -> Vec<usize> {
    let mut pairs: Vec<(String, usize)> = values
        .iter()
        .map(|&v| {
            let input = format!("{}:{}:{}:{}", namespace, seed, ply, v);
            let hash = hex::encode(Sha256::digest(input.as_bytes()));
            (hash, v)
        })
        .collect();
    pairs.sort_by(|a, b| a.0.cmp(&b.0));
    pairs.into_iter().map(|(_, v)| v).collect()
}

pub fn choose_position(policy_id: &str, board: &[String; 9], turn: &str, seed: i64, ply: i64) -> usize {
    let legal = legal_positions(board);

    match policy_id {
        "first_legal_v1" => legal[0],
        "last_legal_v1" => legal[legal.len() - 1],
        "center_first_v1" => {
            if legal.contains(&4) {
                4
            } else {
                legal[0]
            }
        }
        "corner_first_v1" => {
            let mut found = None;
            for &p in &CORNERS {
                if legal.contains(&p) {
                    found = Some(p);
                    break;
                }
            }
            found.unwrap_or(legal[0])
        }
        "edge_first_v1" => {
            let mut found = None;
            for &p in &EDGES {
                if legal.contains(&p) {
                    found = Some(p);
                    break;
                }
            }
            found.unwrap_or(legal[0])
        }
        "win_block_center_v1" => {
            winning_position(board, turn)
                .or_else(|| winning_position(board, opponent(turn)))
                .or_else(|| if legal.contains(&4) { Some(4) } else { None })
                .or_else(|| {
                    for &p in &CORNERS {
                        if legal.contains(&p) {
                            return Some(p);
                        }
                    }
                    None
                })
                .unwrap_or(legal[0])
        }
        "block_win_center_v1" => {
            winning_position(board, opponent(turn))
                .or_else(|| winning_position(board, turn))
                .or_else(|| if legal.contains(&4) { Some(4) } else { None })
                .or_else(|| {
                    for &p in &CORNERS {
                        if legal.contains(&p) {
                            return Some(p);
                        }
                    }
                    None
                })
                .unwrap_or(legal[0])
        }
        "mirror_preferred_v1" => {
            // order: 8,6,2,0,4,7,5,3,1
            let order = [8, 6, 2, 0, 4, 7, 5, 3, 1];
            for &p in &order {
                if legal.contains(&p) {
                    return p;
                }
            }
            legal[0]
        }
        "seeded_legal_v1" => {
            seeded_order(&legal, seed, ply, "tictactoe.seeded_legal_v1")[0]
        }
        "seeded_win_block_v1" => {
            winning_position(board, turn)
                .or_else(|| winning_position(board, opponent(turn)))
                .unwrap_or_else(|| seeded_order(&legal, seed, ply, "tictactoe.seeded_win_block_v1")[0])
        }
        _ => {
            // Fallback for minimax - we inline a simple version
            if policy_id == "minimax_v1" {
                minimax_choose_position(board, turn)
            } else {
                legal[0]
            }
        }
    }
}

fn minimax_score(board: &[String; 9], to_move: &str, maximizing_mark: &str) -> i32 {
    // Check terminal
    if let Some(w) = winner_for(board) {
        return if w == maximizing_mark { 1 } else { -1 };
    }
    let legal: Vec<usize> = (0..9).filter(|&i| board[i].is_empty()).collect();
    if legal.is_empty() {
        return 0; // draw
    }

    if to_move == maximizing_mark {
        let mut best = -2;
        for &idx in &legal {
            let mut next = board.clone();
            next[idx] = to_move.to_string();
            let s = minimax_score(&next, opponent(to_move), maximizing_mark);
            if s > best {
                best = s;
            }
        }
        best
    } else {
        let mut best = 2;
        for &idx in &legal {
            let mut next = board.clone();
            next[idx] = to_move.to_string();
            let s = minimax_score(&next, opponent(to_move), maximizing_mark);
            if s < best {
                best = s;
            }
        }
        best
    }
}

fn minimax_choose_position(board: &[String; 9], mark: &str) -> usize {
    let legal: Vec<usize> = (0..9).filter(|&i| board[i].is_empty()).collect();
    if legal.is_empty() {
        panic!("no legal positions");
    }

    // Check immediate win
    if let Some(pos) = winning_position(board, mark) {
        return pos;
    }
    // Check immediate block
    if let Some(pos) = winning_position(board, opponent(mark)) {
        return pos;
    }

    let mut best_score = -2;
    let mut best_moves: Vec<usize> = Vec::new();
    for &idx in &legal {
        let mut next = board.clone();
        next[idx] = mark.to_string();
        let score = minimax_score(&next, opponent(mark), mark);
        if score > best_score {
            best_score = score;
            best_moves = vec![idx];
        } else if score == best_score {
            best_moves.push(idx);
        }
    }
    best_moves[0]
}

pub fn choose_action(
    policy_id: &str,
    board: &[String; 9],
    turn: &str,
    seed: i64,
    ply: i64,
) -> serde_json::Value {
    let pos = choose_position(policy_id, board, turn, seed, ply);
    serde_json::json!({"player": turn, "position": pos})
}

/// Public/private state split for Tic-Tac-Toe.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PublicState {
    pub board: [String; 9],
    pub turn: String,
    pub winner: Option<String>,
}

impl PublicState {
    pub fn diff(&self, other: &PublicState) -> serde_json::Value {
        use serde_json::json;
        let mut changes = serde_json::Map::new();
        if self.board != other.board {
            changes.insert(
                "board".into(),
                json!({"from": other.board, "to": self.board}),
            );
        }
        if self.turn != other.turn {
            changes.insert(
                "turn".into(),
                json!({"from": other.turn, "to": self.turn}),
            );
        }
        if self.winner != other.winner {
            changes.insert(
                "winner".into(),
                json!({"from": other.winner, "to": self.winner}),
            );
        }
        serde_json::Value::Object(changes)
    }

    pub fn to_dict(&self) -> serde_json::Value {
        serde_json::json!({
            "board": self.board,
            "turn": self.turn,
            "winner": self.winner,
        })
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrivateState {
    pub episode_id: String,
    pub scenario_id: String,
    pub seed: i64,
    pub step_index: i64,
    pub ply: i64,
    pub reward_last: f64,
    pub total_reward: f64,
    pub terminated: bool,
    pub truncated: bool,
}

impl PrivateState {
    pub fn to_dict(&self) -> serde_json::Value {
        serde_json::json!({
            "episode_id": self.episode_id,
            "scenario_id": self.scenario_id,
            "seed": self.seed,
            "step_index": self.step_index,
            "ply": self.ply,
            "reward_last": self.reward_last,
            "total_reward": self.total_reward,
            "terminated": self.terminated,
            "truncated": self.truncated,
        })
    }
}

#[derive(Debug, Clone)]
pub struct SimSnapshot {
    pub public: PublicState,
    pub private: PrivateState,
    pub nev_events: Vec<serde_json::Value>,
}
